export const DESIGN_THINKING_ACTIVITIES = [
{n:1,type:"mcq",micro:"Apa itu berpikir desain",q:"'Berpikir desain' (design thinking) adalah cara memecahkan masalah yang...",options:["Dimulai dari memahami kebutuhan manusia yang akan memakai solusinya, bukan dari solusi","Dimulai dari ide solusi yang paling keren & paling canggih menurut pendapat perancangnya sendiri","Hanya dipakai untuk membuat gambar, poster, dan tampilan yang indah dilihat banyak orang"],answer:0,explain:"Inti berpikir desain: pahami dulu siapa yang punya masalah & apa yang benar-benar mereka butuhkan, baru cari solusi.",hint:"Mulai dari kebutuhan manusia, atau dari solusi keren?"},
{n:2,type:"mcq",micro:"Berpusat pada manusia",q:"'Berpusat pada manusia' berarti solusi dinilai dari...",options:["Seberapa bangga dan puas perasaan pembuat solusi itu terhadap hasil karyanya sendiri di akhir proyek","Seberapa baik ia membantu orang yang dituju dalam situasi nyata mereka","Seberapa canggih dan modern teknologi yang dipakai untuk membuat solusi itu bekerja"],answer:1,explain:"Desain yang berpusat pada manusia terus bertanya 'apakah ini benar-benar membantu mereka?', bukan 'apakah ini mengesankan?'.",hint:"Membantu orang yang dituju, atau terlihat canggih?"},
{n:3,type:"mcq",micro:"Lima tahap",q:"Lima tahap berpikir desain yang umum:",options:["Merancang → Membangun → Menjual → Mendapat untung → Berhenti setelah semua barang terjual habis","Menebak kebutuhan → Membuat solusi → Berharap pengguna menyukainya → Tidak pernah memeriksa lagi","Berempati → Mendefinisikan masalah → Menghasilkan ide → Membuat prototipe → Menguji"],answer:2,explain:"Empati (pahami orang) → Definisikan (rumuskan masalah tepat) → Ide (banyak kemungkinan) → Prototipe (versi kasar) → Uji (belajar dari pengguna).",hint:"Empati-definisi-ide-prototipe-uji, atau langsung membangun?"},
{n:4,type:"mcq",micro:"Masalah dulu, bukan solusi",q:"Kesalahan umum yang dihindari berpikir desain:",options:["Langsung 'jatuh cinta' pada satu solusi sebelum benar-benar memahami masalahnya","Menghabiskan waktu memahami pengguna","Membuat prototipe"],answer:0,explain:"Melompat ke solusi favorit sering menghasilkan sesuatu yang rapi tapi memecahkan masalah yang salah, atau bukan masalah nyata.",hint:"Melompat ke solusi favorit, atau memahami pengguna?"},
{n:5,type:"mcq",micro:"Berempati = memahami",q:"Pada tahap berempati, yang kita lakukan:",options:["Memberi tahu mereka apa yang sebenarnya mereka butuhkan menurut pendapat kita sebagai perancang","Mengamati & berbicara dengan orang yang punya masalah, untuk memahami pengalaman, kesulitan, & kebutuhan mereka","Menebak kebutuhan mereka dari jauh saja tanpa bertemu dan tanpa mengamati keseharian mereka"],answer:1,explain:"Empati dalam desain berarti mengumpulkan pemahaman langsung, bukan berasumsi dari sudut pandang kita sendiri.",hint:"Mengamati & berbicara langsung, atau menebak dari jauh?"},
{n:6,type:"mcq",micro:"Mendefinisikan masalah",q:"Pada tahap mendefinisikan, kita mengubah pengamatan jadi...",options:["Daftar solusi","Kesimpulan bahwa tidak ada masalah","Pernyataan masalah yang jelas & fokus, mis. 'Siswa baru merasa tersesat & sendirian di minggu pertama'"],answer:2,explain:"Pernyataan masalah yang baik cukup sempit untuk dikerjakan, tapi tidak menyebutkan solusi tertentu.",hint:"Pernyataan masalah yang fokus, atau daftar solusi?"},
{n:7,type:"mcq",micro:"'Bagaimana caranya kita'",q:"Mengubah pernyataan masalah jadi pertanyaan 'Bagaimana caranya kita...' berguna untuk...",options:["Membuka tahap menghasilkan ide dengan mengundang banyak kemungkinan solusi","Menutup diskusi","Menyalahkan pihak tertentu"],answer:0,explain:"'Bagaimana caranya kita membuat siswa baru merasa diterima?' mengundang ide tanpa membatasi bentuknya.",hint:"Mengundang banyak solusi, atau menutup diskusi?"},
{n:8,type:"mcq",micro:"Prototipe & uji dalam desain",q:"Setelah punya ide terpilih, berpikir desain menyarankan...",options:["Berhenti di situ saja dan berharap idenya sudah benar tanpa perlu dicoba oleh pengguna mana pun","Membuat prototipe kasar & mengujinya dengan pengguna sungguhan sebelum membuat versi jadi","Langsung membuat versi finalnya yang lengkap dan rapi supaya cepat bisa dipakai oleh banyak orang"],answer:1,explain:"Prototipe & uji mengubah tebakan jadi bukti, & sering mengirim kita kembali ke tahap sebelumnya dengan pemahaman baru.",hint:"Prototipe & uji dulu, atau langsung final?"},
{n:9,type:"order",micro:"Alur berpikir desain",q:"Urutkan lima tahap berpikir desain.",items:["Berempati: pahami orang & situasinya","Mendefinisikan: rumuskan masalah yang tepat","Menghasilkan ide: cari banyak kemungkinan solusi","Membuat prototipe & menguji: buat versi kasar, coba dengan pengguna, pelajari"],answer:[0,1,2,3],explain:"Pahami → rumuskan → ide → prototipe & uji. Urutan ini menjaga solusi tetap menempel pada kebutuhan nyata.",hint:"Merumuskan masalah sebelum atau sesudah memahami orang?"},
{n:10,type:"mcq",micro:"Tahap tidak selalu lurus",q:"Dalam praktik, tahap-tahap berpikir desain...",options:["Selalu dijalankan hanya sekali secara lurus dari tahap pertama sampai tahap terakhir tanpa diulang","Bisa dilewati semuanya karena perancang yang berpengalaman sudah tahu jawabannya sejak awal","Sering diulang & dilompati bolak-balik, mis. hasil uji membuat kita mendefinisikan ulang masalah"],answer:2,explain:"Berpikir desain adalah proses berputar. Menemukan hal baru di tahap akhir sering mengirim kita kembali ke awal, & itu normal.",hint:"Berputar & bolak-balik, atau lurus sekali jalan?"},
{n:11,type:"tf",micro:"Desain untuk orang lain, bukan diri sendiri",q:"Benar atau Salah: Dalam berpikir desain, solusi dirancang untuk kebutuhan pengguna yang dituju, bukan untuk selera pribadi perancang.",answer:true,explain:"Perancang mudah berasumsi 'yang kusukai pasti disukai semua'. Berpikir desain mengoreksi ini dengan terus kembali ke pengguna.",hint:"Untuk pengguna yang dituju, atau selera perancang?"},
{n:12,type:"tf",micro:"Berpikir desain hanya untuk seniman?",q:"Benar atau Salah: Berpikir desain hanya berguna untuk orang yang pandai menggambar atau membuat produk fisik.",answer:false,explain:"Sebaliknya, berpikir desain dipakai untuk merancang layanan, acara, aturan, pelajaran, ruang, apa pun yang dipakai manusia. Menggambar hanya salah satu alat, bukan syarat.",hint:"Hanya untuk seniman, atau untuk apa pun yang dipakai manusia?"},
{n:13,type:"mcq",micro:"Tanda memahami pengguna",q:"Kamu cukup memahami pengguna ketika bisa...",options:["Menceritakan kebutuhan, kesulitan, & harapan mereka dengan kata-katamu sendiri, dengan contoh nyata","Menebak apa yang mereka inginkan berdasarkan perasaan kita tanpa perlu bertanya kepada mereka","Mengatakan dengan yakin bahwa 'semua orang butuh ini' tanpa menyebut siapa orangnya dan apa kesulitannya"],answer:0,explain:"Pemahaman yang nyata terdengar spesifik ('siswa baru bingung di mana ruang UKS & malu bertanya'), bukan umum.",hint:"Spesifik dengan contoh, atau menebak / umum?"},
{n:14,type:"mcq",micro:"Prototipe sebagai bahasa",q:"Dalam berpikir desain, prototipe membantu tim karena...",options:["Menggantikan kebutuhan untuk berbicara dengan pengguna sehingga tim tidak perlu lagi bertanya kepada mereka","Membuat ide jadi konkret sehingga semua bisa melihat & mendiskusikan hal yang sama","Membuat ide tetap menjadi rahasia di dalam kepala tim sehingga tidak ada pihak luar yang bisa meniru"],answer:1,explain:"Kata-kata bisa ditafsirkan berbeda. Prototipe menyamakan gambaran & memancing umpan balik yang spesifik.",hint:"Menyamakan gambaran, atau membuat rahasia?"},
{n:15,type:"mcq",micro:"Menghasilkan banyak ide dulu",q:"Pada tahap ide, berpikir desain menyarankan...",options:["Langsung memilih ide pertama yang muncul di kepala supaya prosesnya cepat dan tim tidak bingung","Hanya boleh menyebut ide yang sudah pasti berhasil agar waktu tim tidak terbuang untuk ide yang gagal","Menghasilkan banyak ide beragam tanpa menilai dulu, baru menyaring setelahnya"],answer:2,explain:"Ide bagus jarang yang pertama. Menunda penilaian & mengejar keberagaman memberi lebih banyak pilihan untuk disaring.",hint:"Banyak dulu lalu saring, atau ambil yang pertama?"},
{n:16,type:"tf",micro:"Uji dengan pengguna nyata",q:"Benar atau Salah: Menguji prototipe dengan teman dekat yang sudah tahu maksud kita lebih berharga daripada menguji dengan orang yang mewakili pengguna sebenarnya.",answer:false,explain:"Sebaliknya, teman dekat cenderung memuji & memakai sesuai maksud kita. Pengguna nyata menunjukkan kebingungan & kebutuhan yang sebenarnya.",hint:"Pengguna nyata, atau teman dekat yang paham maksud kita?"},
{n:17,type:"mcq",micro:"Desain & konteks",q:"Solusi desain perlu mempertimbangkan 'konteks', yaitu...",options:["Situasi nyata tempat solusi dipakai: siapa, kapan, di mana, dengan alat & keterbatasan apa","Hanya tampilan luar dari solusinya saja, seperti warna, bentuk, dan hiasan yang membuatnya terlihat bagus","Pendapat perancang saja, sebab perancang yang paling tahu bagaimana solusinya akan dipakai orang"],answer:0,explain:"Solusi yang bagus di ruang rapat bisa gagal di lapangan kalau konteks pemakaian nyata (bising, terburu-buru, tangan kotor) diabaikan.",hint:"Situasi nyata pemakaian, atau hanya tampilan?"},
{n:18,type:"mcq",micro:"Desain melayani, bukan memamerkan",q:"Tanda sebuah solusi desain berhasil:",options:["Membuat perancangnya menjadi terkenal sehingga banyak orang menyebut namanya dalam berbagai acara","Orang yang dituju bisa memakainya dengan mudah untuk mencapai tujuan mereka","Terlihat rumit & mengesankan sehingga orang yang melihatnya langsung kagum pada kepintaran pembuatnya"],answer:1,explain:"Desain terbaik sering 'tidak terlihat', ia bekerja begitu mulus sehingga pengguna tidak memikirkannya.",hint:"Mudah dipakai untuk tujuan pengguna, atau terlihat mengesankan?"},
{n:19,type:"mcq",micro:"Berpikir desain & kerja sama",q:"Berpikir desain biasanya dikerjakan...",options:["Sendirian saja selalu, supaya tidak ada perbedaan pendapat yang memperlambat jalannya pekerjaan","Oleh satu orang ahli yang memutuskan semuanya sendiri, sedangkan anggota lain hanya mengikuti","Dalam tim dengan sudut pandang beragam, karena tiap orang menangkap kebutuhan & ide yang berbeda"],answer:2,explain:"Keragaman tim (& melibatkan pengguna) memperkaya empati & ide, serta mengurangi titik buta.",hint:"Tim beragam, atau satu ahli memutuskan?"},
{n:20,type:"open",micro:"Kenali sebuah masalah desain",q:"Pilih satu hal di sekolah atau lingkunganmu yang menurutmu 'kurang dirancang dengan baik' untuk orang yang memakainya (mis. papan pengumuman yang selalu diabaikan, tempat parkir sepeda yang berantakan, cara mendaftar kegiatan). Tulis: (a) siapa penggunanya, (b) 3 kesulitan yang mereka alami (dugaan dari pengamatanmu), (c) 2 pertanyaan yang akan kamu tanyakan ke pengguna sungguhan untuk memahami lebih dalam, (d) kenapa langsung mengusulkan solusi sekarang bisa keliru.",explain:"Jawaban baik: pengguna yang spesifik, 3 kesulitan yang masuk akal dari pengamatan (bukan asumsi liar), 2 pertanyaan terbuka yang menggali pengalaman & kebutuhan (bukan pertanyaan ya/tidak), & penjelasan yang menunjukkan paham kenapa memahami dulu penting, bahwa solusi cepat bisa menyasar masalah yang salah.",hint:"Pertanyaan (c) sebaiknya minta orang menceritakan pengalaman nyata langkah demi langkah, di situ kesulitan tersembunyi biasanya muncul.",sample:"Hal: cara mendaftar kegiatan ekstrakurikuler, saat ini lewat menuliskan nama di kertas yang ditempel di papan dekat ruang guru. (a) Pengguna: semua siswa yang ingin ikut ekskul, terutama siswa kelas 7 yang baru. (b) Kesulitan yang kuduga: (1) Kertasnya sering penuh atau sobek, jadi orang tidak tahu apakah masih ada kuota. (2) Papan itu di lokasi yang jarang dilewati siswa kelas 7, jadi banyak yang tidak tahu pendaftaran sudah dibuka. (3) Tidak ada informasi jelas tentang jadwal & syarat tiap ekskul di sana, jadi orang mendaftar lalu bingung atau menyesal. (c) Pertanyaan ke pengguna: 'Ceritakan bagaimana kamu terakhir kali mendaftar ekskul, dari tahu ada pendaftaran sampai selesai, bagian mana yang membingungkan?' & 'Informasi apa yang kamu harap ada tapi tidak kamu temukan waktu itu?' (d) Kenapa langsung mengusulkan solusi bisa keliru: aku baru menebak kesulitannya dari pengamatan, belum memastikan. Mungkin masalah sebenarnya bukan papannya, tapi tidak adanya pengumuman jelas, atau siswa takut ekskul favoritnya penuh sehingga tidak berani menunggu. Kalau aku langsung membuat 'formulir digital' padahal masalah utamanya adalah kurang informasi tentang ekskulnya, solusiku rapi tapi tidak menyelesaikan masalah yang benar."},
{n:21,type:"classify",micro:"Berpusat pada manusia vs berpusat pada solusi",q:"Kelompokkan tiap pendekatan ke 'Berpusat pada manusia' atau 'Berpusat pada solusi sendiri'.",items:["'Ayo kita tanya & amati dulu bagaimana mereka mengalami masalah ini'","'Aku sudah tahu jawabannya, tinggal dibuat'","'Uji coba ke beberapa pengguna nyata, lihat di mana mereka kesulitan'","'Yang penting solusinya terlihat modern & keren'"],groups:["Berpusat pada manusia","Berpusat pada solusi sendiri"],answer:{"Berpusat pada manusia":["'Ayo kita tanya & amati dulu bagaimana mereka mengalami masalah ini'","'Uji coba ke beberapa pengguna nyata, lihat di mana mereka kesulitan'"],"Berpusat pada solusi sendiri":["'Aku sudah tahu jawabannya, tinggal dibuat'","'Yang penting solusinya terlihat modern & keren'"]},explain:"Berpusat pada manusia: mulai & kembali ke pengguna. Berpusat pada solusi: mulai & bertahan pada ide sendiri.",hint:"Kembali ke pengguna, atau bertahan pada ide sendiri?"},
{n:22,type:"mcq",micro:"Wawancara empati",q:"Pertanyaan yang baik saat mewawancarai pengguna untuk memahami masalah:",options:["'Coba ceritakan terakhir kali kamu mengalami ini, dari awal sampai akhir'","'Kamu pasti butuh aplikasi buatanku ini, kan? Bagian mana yang paling kamu suka dari aplikasi itu?'","'Menurutmu solusi yang sudah kubuat ini bagus tidak? Coba katakan saja yang bagus-bagusnya dulu.'"],answer:0,explain:"Minta cerita pengalaman nyata & spesifik. Hindari pertanyaan yang mengarahkan jawaban atau menanyakan solusi kita.",hint:"Minta cerita pengalaman nyata, atau menanyakan solusi kita?"},
{n:23,type:"mcq",micro:"Mengamati vs bertanya",q:"Kenapa mengamati orang memakai sesuatu sering lebih berharga daripada hanya menanyai mereka?",options:["Bertanya tidak pernah berguna karena orang selalu berbohong atau menjawab asal ketika diwawancarai","Orang sering tidak sadar atau lupa menyebut kesulitan yang mereka alami; tindakan mereka menunjukkannya","Mengamati selalu lebih cepat daripada bertanya sehingga wawancara tidak perlu dilakukan sama sekali"],answer:1,explain:"'Aku sih tidak kesulitan' sering diucapkan oleh orang yang jelas-jelas kesulitan saat diamati. Perilaku lebih jujur daripada ingatan.",hint:"Tindakan mengungkap kesulitan yang tak disadari, atau bertanya tak berguna?"},
{n:24,type:"mcq",micro:"Peta perjalanan pengguna",q:"'Peta perjalanan pengguna' menggambarkan...",options:["Rute jalan kaki yang dilalui seseorang dari rumahnya menuju sekolah setiap hari beserta jaraknya","Silsilah keluarga dari pengguna yang diwawancarai beserta nama kakek-neneknya dari generasi dahulu","Langkah demi langkah yang dilalui seseorang saat memakai/mengalami sesuatu, & perasaan mereka di tiap langkah"],answer:2,explain:"Memetakan 'siswa baru: masuk gerbang → bingung arah → tanya satpam → salah ruang → terlambat → malu' menunjukkan di mana masalahnya paling terasa.",hint:"Langkah & perasaan sepanjang pengalaman, atau rute jalan?"},
{n:25,type:"mcq",micro:"Wawasan (insight)",q:"'Wawasan' dalam berpikir desain adalah...",options:["Pemahaman menarik tentang KENAPA pengguna mengalami masalah, yang membuka arah solusi baru","Daftar semua keluhan pengguna yang dicatat dari wawancara tanpa diolah atau dicari alasannya","Solusi yang sudah jadi dan siap dipakai karena perancang sudah memahami apa yang dibutuhkan pengguna"],answer:0,explain:"Dari 'siswa baru tidak bertanya arah' → wawasan: 'mereka takut terlihat bodoh di depan kakak kelas'. Wawasan ini mengarahkan solusi (mis. peer buddy, bukan sekadar papan petunjuk).",hint:"Pemahaman tentang KENAPA, atau daftar keluhan?"},
{n:26,type:"mcq",micro:"Persona",q:"'Persona' adalah...",options:["Nama samaran yang dipakai perancang ketika ia tidak ingin identitas aslinya diketahui oleh pengguna","Gambaran satu pengguna khas (kebiasaan, kebutuhan, kesulitan) yang mewakili sekelompok pengguna nyata, dibuat dari data pengamatan","Tokoh khayalan yang diciptakan sesuka hati perancang tanpa dasar dari pengamatan pengguna sebenarnya"],answer:1,explain:"Persona ('Rani, kelas 7, pemalu, pertama kali di sekolah besar') membantu tim mengingat mereka merancang untuk siapa.",hint:"Gambaran pengguna khas dari data nyata, atau tokoh khayalan?"},
{n:27,type:"tf",micro:"Pernyataan masalah tanpa solusi",q:"Benar atau Salah: Pernyataan masalah yang baik sebaiknya sudah menyebutkan solusi tertentu yang akan dipakai, supaya arahnya jelas sejak awal.",answer:false,explain:"Sebaliknya, pernyataan yang baik menyebut siapa & kesulitannya tanpa mengunci solusi: 'siswa baru butuh cara merasa terbimbing' membuka banyak solusi, sedangkan 'kita butuh aplikasi peta sekolah' mengunci terlalu dini.",hint:"Bebas dari solusi tertentu, atau langsung menyebut solusi?"},
{n:28,type:"tf",micro:"Empati butuh keluar dari asumsi",q:"Benar atau Salah: Tujuan tahap berempati adalah mengganti asumsi kita tentang pengguna dengan pemahaman yang didasari pengamatan & percakapan nyata.",answer:true,explain:"Kita semua membawa asumsi ('anak zaman sekarang pasti nyaman dengan teknologi'). Empati menguji asumsi itu terhadap kenyataan.",hint:"Mengganti asumsi dengan pemahaman nyata, atau memperkuat asumsi?"},
{n:29,type:"mcq",micro:"Mempersempit masalah",q:"Setelah berempati, kamu menemukan 10 masalah berbeda. Langkah berikutnya:",options:["Coba selesaikan kesepuluh masalah itu sekaligus supaya tidak ada pengguna yang merasa terlupakan","Pilih masalah yang paling mudah dikerjakan saja tanpa memikirkan seberapa penting masalah itu bagi pengguna","Pilih 1-2 masalah yang paling penting bagi pengguna & paling mungkin dikerjakan, jadikan fokus"],answer:2,explain:"Fokus adalah kekuatan. Menyelesaikan satu masalah penting dengan baik lebih berharga daripada menyentuh sepuluh secara dangkal.",hint:"Fokus ke 1-2 yang penting & bisa dikerjakan, atau semua sekaligus?"},
{n:30,type:"order",micro:"Dari empati ke definisi",q:"Urutkan langkah mengubah hasil empati jadi pernyataan masalah.",items:["Kumpulkan catatan wawancara & pengamatan","Kelompokkan temuan yang mirip & cari pola","Rumuskan 1-2 wawasan (kenapa masalah ini terjadi)","Tulis pernyataan masalah: [pengguna] butuh [kebutuhan] karena [wawasan]"],answer:[0,1,2,3],explain:"Kumpulkan → kelompokkan → wawasan → pernyataan masalah. Pernyataan yang baik lahir dari pola, bukan dari satu percakapan.",hint:"Merumuskan wawasan sebelum atau sesudah mengelompokkan temuan?"},
{n:31,type:"mcq",micro:"Jumlah orang yang diwawancarai",q:"Untuk proyek desain kecil (kelas/sekolah), berapa pengguna yang cukup diajak bicara di tahap empati?",options:["Sekitar 5-8 orang yang beragam biasanya sudah menunjukkan pola kebutuhan utama","Minimal 500 orang","Cukup 1 orang, itu pasti mewakili semua"],answer:0,explain:"Beberapa percakapan mendalam dengan orang yang beragam lebih berguna daripada survei singkat ke banyak orang, untuk tahap ini.",hint:"5-8 orang beragam, atau ratusan / satu?"},
{n:32,type:"tf",micro:"Definisi bisa berubah",q:"Benar atau Salah: Setelah pernyataan masalah ditetapkan, ia tidak boleh diubah meski tahap uji mengungkap pemahaman baru.",answer:false,explain:"Sebaliknya, menemukan saat uji bahwa 'masalah sebenarnya bukan ini' adalah hasil berharga. Berpikir desain justru memperbolehkan kembali & mendefinisikan ulang.",hint:"Bisa direvisi setelah belajar, atau harus tetap?"},
{n:33,type:"mcq",micro:"Kebutuhan vs keinginan permukaan",q:"Pengguna berkata 'aku mau tombol yang lebih besar'. Perancang yang baik...",options:["Mengabaikan permintaannya karena pengguna biasanya tidak tahu apa yang sebenarnya mereka butuhkan","Menggali: 'kenapa? apa yang menyulitkan sekarang?' Mungkin kebutuhan sebenarnya adalah 'sulit menemukan tombol dengan cepat'","Langsung membuat tombolnya jadi besar tanpa bertanya apa-apa agar pengguna cepat merasa dituruti"],answer:1,explain:"Permintaan pengguna adalah petunjuk menuju kebutuhan, bukan spesifikasi solusi. Gali 'kenapa' untuk menemukan kebutuhan asli.",hint:"Gali kenapa untuk menemukan kebutuhan asli, atau turuti/abaikan mentah?"},
{n:34,type:"mcq",micro:"Empati pada pengguna yang berbeda dari kita",q:"Saat merancang untuk kelompok yang sangat berbeda dari kita (lansia, anak kecil, penyandang disabilitas), yang penting:",options:["Menganggap kebutuhan mereka pasti sama saja dengan kebutuhan kita sehingga tidak perlu repot bertanya","Merancang berdasarkan bayangan kita sendiri tentang mereka, karena kita merasa sudah cukup mengerti","Benar-benar melibatkan mereka dalam proses, bukan menebak kebutuhan mereka dari kursi kita"],answer:2,explain:"'Tidak ada tentang kami tanpa kami', kelompok yang dituju harus punya suara nyata dalam proses, terutama yang jauh dari pengalaman perancang.",hint:"Libatkan mereka langsung, atau menebak dari kursi kita?"},
{n:35,type:"mcq",micro:"Sintesis temuan",q:"'Sintesis' setelah tahap empati berarti...",options:["Menyatukan banyak potongan pengamatan jadi beberapa pemahaman inti yang bisa dipakai","Menyalin semua catatan pengamatan ke satu dokumen besar tanpa diolah atau dicari pola di dalamnya","Membuang semua catatan lalu mengandalkan ingatan saja untuk menentukan apa yang penting bagi pengguna"],answer:0,explain:"Data mentah dari 8 wawancara terlalu banyak untuk dipakai langsung. Sintesis mengubahnya jadi 2-3 wawasan yang tajam.",hint:"Menyatukan jadi pemahaman inti, atau menyalin mentah?"},
{n:36,type:"mcq",micro:"Pernyataan masalah yang terlalu luas",q:"Masalah 'Sekolah kami kurang menyenangkan' terlalu luas untuk dikerjakan. Versi yang lebih baik:",options:["'Kepala sekolah harus lebih baik dalam memimpin dan memperhatikan semua murid di sekolah ini.'","'Siswa merasa waktu istirahat terlalu singkat & tidak ada kegiatan menarik yang bisa diselesaikan dalam waktu itu'","'Semua hal di sekolah kami harus diperbaiki sekaligus supaya sekolah ini menjadi tempat yang lebih baik.'"],answer:1,explain:"Pernyataan yang fokus pada satu aspek & pengguna tertentu bisa dikerjakan. Yang terlalu luas melumpuhkan.",hint:"Fokus & spesifik, atau luas & menyalahkan?"},
{n:37,type:"tf",micro:"Empati bukan sekadar simpati",q:"Benar atau Salah: Berempati dalam desain cukup dengan merasa kasihan pada pengguna; tidak perlu benar-benar memahami pengalaman & kebutuhan mereka.",answer:false,explain:"Sebaliknya, simpati ('kasihan ya') tidak menghasilkan solusi. Empati desain ('aku paham persis di mana & kenapa mereka tersendat') menghasilkan arah yang jelas.",hint:"Memahami pengalaman & kebutuhan, atau sekadar merasa kasihan?"},
{n:38,type:"mcq",micro:"Titik nyeri (pain point)",q:"'Titik nyeri' pengguna adalah...",options:["Bagian tubuh pengguna yang terasa sakit ketika mereka memakai solusi yang sudah kita buat","Bagian dari solusi yang paling mahal biayanya sehingga perlu dihemat atau dikurangi oleh perancang","Momen atau bagian tertentu di mana pengguna merasa frustrasi, bingung, atau terhambat"],answer:2,explain:"Mengidentifikasi titik nyeri ('saat harus mengisi formulir tiga kali') menunjukkan di mana solusi paling dibutuhkan.",hint:"Momen frustrasi/terhambat pengguna, atau bagian termahal?"},
{n:39,type:"mcq",micro:"Empati & tetap kritis",q:"Saat pengguna memberi banyak masukan, perancang tetap perlu...",options:["Menimbang mana yang mencerminkan kebutuhan nyata & mana yang selera pribadi satu orang, cari pola","Menuruti setiap masukan pengguna persis seperti yang mereka katakan tanpa memilih atau mempertimbangkannya","Mengabaikan semua masukan pengguna karena perancang lebih tahu mana yang terbaik untuk mereka semua"],answer:0,explain:"Empati berarti mendengar sungguh-sungguh, lalu mengolah. Pola keluhan berulang lebih penting daripada preferensi tunggal.",hint:"Timbang & cari pola, atau turuti semua / abaikan?"},
{n:40,type:"open",micro:"Wawancara & pernyataan masalah",q:"Pilih satu masalah yang menyangkut orang lain (bukan dirimu sendiri). Tulis: (a) 4 pertanyaan wawancara empati yang akan kamu ajukan (terbuka, tentang pengalaman nyata, bukan tentang solusimu), (b) berdasarkan yang kamu perkirakan akan mereka jawab, tulis 1 wawasan (kenapa masalah terjadi), (c) satu pernyataan masalah dengan format '[pengguna] butuh [kebutuhan] karena [wawasan]', (d) satu pertanyaan 'Bagaimana caranya kita...' dari pernyataan itu.",explain:"Jawaban baik: 4 pertanyaan yang terbuka & meminta cerita pengalaman nyata (bukan 'apakah kamu suka ideku'), wawasan yang menjelaskan KENAPA (bukan mengulang keluhan), pernyataan masalah dalam format yang diminta & bebas dari solusi tertentu, & pertanyaan 'bagaimana caranya kita' yang mengundang banyak solusi.",hint:"Pastikan pernyataan masalahmu tidak menyebut solusi apa pun (jangan tulis 'butuh aplikasi' atau 'butuh loker'), hanya kebutuhan & alasannya.",sample:"Masalah: adik kelas sering kehilangan barang di sekolah (jaket, botol minum, kotak pensil). (a) Pertanyaan wawancara: (1) 'Coba ceritakan terakhir kali kamu kehilangan barang di sekolah, dari kapan kamu sadar hilang sampai apa yang kamu lakukan.' (2) 'Di bagian hari yang mana kamu paling sering meninggalkan barang, & sedang melakukan apa waktu itu?' (3) 'Kalau menemukan barang orang lain, biasanya kamu apakan?' (4) 'Apa yang membuatmu ragu atau malas mencoba mencari barang yang hilang?' (b) Wawasan perkiraan: barang hilang paling sering saat perpindahan cepat antar kegiatan (olahraga, pindah kelas), & anak jarang mencari kembali karena tidak tahu ke mana barang temuan dikumpulkan & merasa 'percuma'. (c) Pernyataan masalah: 'Siswa kelas bawah butuh cara mudah menemukan kembali barang yang tertinggal, karena barang paling sering hilang saat berpindah kegiatan dengan terburu-buru & tidak ada tempat kumpul barang temuan yang mereka ketahui.' (d) Bagaimana caranya kita: 'Bagaimana caranya kita membuat barang yang tertinggal mudah dikembalikan ke pemiliknya, terutama setelah kegiatan yang membuat siswa terburu-buru?'"},
{n:41,type:"mcq",micro:"Berpindah antar tahap",q:"Kamu di tahap prototipe & sadar belum benar-benar paham pengguna. Sikap yang tepat:",options:["Menyerah pada proyek itu karena merasa sudah terlambat dan tidak mungkin memahami pengguna lagi","Kembali sebentar ke tahap empati untuk mengisi kekosongan itu, lalu lanjutkan","Terus membuat prototipe berdasarkan tebakan saja supaya jadwal proyek tetap berjalan sesuai rencana"],answer:1,explain:"Berpikir desain memperbolehkan mundur. Prototipe berdasarkan pemahaman yang bolong akan menghasilkan solusi yang meleset.",hint:"Kembali mengisi kekosongan empati, atau lanjut dengan tebakan?"},
{n:42,type:"mcq",micro:"Menghubungkan dengan curah gagasan",q:"Pada tahap menghasilkan ide dalam berpikir desain, teknik yang cocok:",options:["Langsung memilih satu ide saja tanpa membuat alternatif lain supaya prosesnya cepat dan tidak berbelit","Menyalin solusi dari sekolah lain persis seperti aslinya tanpa menyesuaikannya dengan kebutuhan kita","Curah gagasan dari pernyataan 'bagaimana caranya kita', kejar jumlah & keragaman, tunda penilaian"],answer:2,explain:"Tahap ide butuh mode 'melebar': banyak kemungkinan dulu. Menyaring & memilih adalah langkah berikutnya.",hint:"Curah gagasan dari 'bagaimana caranya kita', atau langsung pilih satu?"},
{n:43,type:"mcq",micro:"Menghubungkan dengan prototipe",q:"Setelah memilih 1-2 ide, langkah berpikir desain berikutnya:",options:["Buat prototipe kasar & cepat yang menguji bagian paling meragukan dari ide itu","Buat versi final yang lengkap dan rapi supaya bisa langsung dibagikan kepada seluruh pengguna sekaligus","Tulis laporan yang panjang dan terperinci tentang idenya tanpa pernah mencoba versi kasarnya dahulu"],answer:0,explain:"Prototipe menghubungkan ide dengan kenyataan. Kasar & cepat, fokus pada pertanyaan yang paling ingin dijawab.",hint:"Prototipe kasar yang menguji bagian meragukan, atau versi final?"},
{n:44,type:"mcq",micro:"Menghubungkan dengan uji & iterasi",q:"Hasil menguji prototipe dengan pengguna dipakai untuk...",options:["Berhenti di situ tanpa mengubah apa pun, sebab pengujian hanya untuk memenuhi tugas dari guru","Memperbaiki solusi, atau bila perlu kembali mendefinisikan ulang masalah, lalu ulangi","Membuktikan bahwa ide kita sudah benar sehingga tidak perlu ada lagi perbaikan sesudah pengujian"],answer:1,explain:"Uji adalah sumber pembelajaran. Temuan mengirim kita maju (perbaiki) atau mundur (definisikan ulang), keduanya kemajuan.",hint:"Memperbaiki / mendefinisikan ulang, atau membuktikan kita benar?"},
{n:45,type:"tf",micro:"Prototipe cepat mengalahkan rencana panjang",q:"Benar atau Salah: Untuk ide yang belum teruji, membuat prototipe kasar & mengujinya biasanya mengajari lebih banyak daripada menulis rencana rinci berhalaman-halaman.",answer:true,explain:"Rencana rinci untuk ide yang belum teruji berdasarkan tebakan. Prototipe & uji menggantikan tebakan dengan bukti sebelum merencanakan detail.",hint:"Prototipe & uji, atau rencana rinci dulu?"},
{n:46,type:"mcq",micro:"Sesi 'bagaimana caranya kita' yang baik",q:"Satu pernyataan masalah bisa menghasilkan beberapa pertanyaan 'bagaimana caranya kita' dengan sudut berbeda. Manfaatnya:",options:["Membingungkan tim tanpa manfaat sama sekali karena terlalu banyak pertanyaan yang berbeda-beda","Cukup satu pertanyaan saja, sebab banyak sudut hanya akan membuat tim sulit memilih arah yang tepat","Tiap sudut membuka kumpulan ide berbeda, memperluas ruang solusi"],answer:2,explain:"'Bagaimana caranya kita membuat siswa baru merasa dikenal' vs '...membuat mereka tahu arah' vs '...membuat kakak kelas mau membantu', masing-masing memicu solusi berbeda.",hint:"Tiap sudut membuka ide berbeda, atau satu cukup?"},
{n:47,type:"mcq",micro:"Kriteria memilih ide",q:"Setelah curah gagasan, memilih ide untuk diprototipe sebaiknya berdasarkan...",options:["Seberapa baik menjawab kebutuhan pengguna, seberapa mungkin dikerjakan dengan sumber daya yang ada, & seberapa banyak yang bisa dipelajari dari mengujinya","Ide yang diusulkan oleh anggota yang paling populer di kelompok karena paling mudah diterima semua orang","Ide yang paling rumit & paling canggih supaya hasilnya terlihat mengesankan bagi juri dan penonton"],answer:0,explain:"Kriteria yang jelas & terhubung ke pengguna serta kelayakan membuat pemilihan bisa dijelaskan & adil.",hint:"Kebutuhan pengguna + kelayakan + potensi belajar, atau populer / rumit?"},
{n:48,type:"mcq",micro:"Uji tanpa memandu",q:"Saat pengguna mencoba prototipemu, sebaiknya kamu...",options:["Membela setiap bagian yang mereka kritik supaya mereka mengerti alasan di balik tiap keputusan desain","Beri tugas nyata lalu diam & amati di mana mereka ragu atau salah, tanpa terus menuntun","Terus menjelaskan cara memakainya selama mereka mencoba supaya mereka tidak membuat kesalahan apa pun"],answer:1,explain:"Kalau kamu menuntun, kamu menguji penjelasanmu, bukan kejelasan desainmu. Menahan diri mengungkap masalah nyata.",hint:"Diam & amati, atau terus menuntun / membela?"},
{n:49,type:"mcq",micro:"Mendokumentasikan proses",q:"Menyimpan catatan tiap tahap (wawancara, pernyataan masalah, ide, prototipe, hasil uji) berguna karena...",options:["Membuat proyek terlihat memiliki lebih banyak pekerjaan sehingga nilai dari guru bisa lebih tinggi","Tidak berguna lagi setelah proyek selesai, sehingga catatan itu bisa dibuang begitu saja ke tempat sampah","Menunjukkan bagaimana solusi berkembang, memudahkan menjelaskan keputusan, & membantu proyek berikutnya"],answer:2,explain:"Jejak proses membuat keputusan bisa dipertanggungjawabkan ('kami memilih ini karena 6 dari 8 pengguna menyebut...') & menjadi pelajaran untuk lain kali.",hint:"Menunjukkan perkembangan & keputusan, atau sekadar terlihat banyak?"},
{n:50,type:"order",micro:"Satu siklus berpikir desain mini",q:"Urutkan langkah menjalankan satu siklus berpikir desain kecil dalam dua minggu.",items:["Minggu 1 awal: wawancara/amati 5-6 pengguna, rumuskan pernyataan masalah","Minggu 1 akhir: curah gagasan solusi, pilih 1-2 ide","Minggu 2 awal: buat prototipe kasar, uji ke 3-5 pengguna","Minggu 2 akhir: perbaiki berdasar temuan (atau definisikan ulang masalah), siapkan hasil"],answer:[0,1,2,3],explain:"Empati & definisi → ide & pilih → prototipe & uji → perbaiki/redefinisi. Satu siklus penuh, kecil tapi lengkap.",hint:"Curah gagasan sebelum atau sesudah merumuskan pernyataan masalah?"},
{n:51,type:"mcq",micro:"Melibatkan pengguna sepanjang proses",q:"Cara terbaik menjaga solusi tetap berpusat pada manusia:",options:["Libatkan pengguna di banyak titik: empati, uji ide awal, uji prototipe, bukan hanya di awal","Wawancara sekali saja di awal proyek lalu tidak melibatkan mereka lagi sampai solusinya selesai dibuat","Libatkan mereka hanya untuk menyetujui hasil akhir supaya mereka merasa dihargai oleh tim perancang"],answer:0,explain:"Kebutuhan & pemahaman berkembang. Kembali ke pengguna berulang kali menjaga solusi tidak menyimpang dari kenyataan.",hint:"Libatkan di banyak titik, atau sekali di awal?"},
{n:52,type:"tf",micro:"Berpikir desain untuk masalah abstrak",q:"Benar atau Salah: Berpikir desain hanya bisa dipakai untuk merancang benda, bukan untuk masalah 'lunak' seperti 'membuat rapat kelas lebih efektif' atau 'mengurangi cemas saat ujian'.",answer:false,explain:"Sebaliknya, selama ada manusia dengan kebutuhan & pengalaman, langkah empati-definisi-ide-prototipe-uji berlaku. Prototipenya bisa berupa mencoba format rapat baru sekali.",hint:"Bisa untuk masalah lunak, atau hanya benda?"},
{n:53,type:"mcq",micro:"Prototipe untuk ide layanan",q:"Untuk ide 'sesi tanya-jawab santai dengan kakak kelas untuk siswa baru', prototipenya:",options:["Bayangkan saja di kepala bagaimana kira-kira jadinya sesi itu tanpa perlu mencoba menjalankannya","Jalankan satu sesi kecil dengan beberapa sukarelawan, amati dinamikanya & tanya perasaan peserta, perbaiki sebelum dijadikan program","Buat aturan resmi yang lengkap lalu umumkan langsung ke seluruh angkatan agar semua siswa baru ikut"],answer:1,explain:"Layanan diprototipe dengan menjalankannya kecil & singkat, memperhatikan pengalaman peserta.",hint:"Jalankan sesi kecil & amati, atau umumkan resmi langsung?"},
{n:54,type:"mcq",micro:"Menahan diri dari solusi favorit",q:"Selama tahap empati, kamu sudah membayangkan solusi yang kamu suka. Sikap yang tepat:",options:["Langsung mulai membuat solusi favoritmu itu supaya waktu proyek tidak terbuang untuk hal lain lagi","Berhenti berempati karena kamu sudah punya jawaban dan merasa tidak perlu mendengar pengguna lagi","Catat idenya, tapi tetap fokus memahami pengguna dulu, mungkin pemahaman baru akan mengubah atau memperbaiki ide itu"],answer:2,explain:"Ide awal boleh ada, tapi 'menguncinya' terlalu dini membuat kita mendengar pengguna secara selektif, hanya yang mendukung ide kita.",hint:"Catat & tetap berempati, atau langsung buat solusi favorit?"},
{n:55,type:"mcq",micro:"Menguji dua konsep",q:"Kamu punya dua konsep solusi & tidak yakin mana yang lebih baik. Pendekatan desain:",options:["Buat prototipe kasar keduanya, tunjukkan ke pengguna, & bandingkan reaksi & kesesuaian dengan kebutuhan","Pilih berdasarkan selera tim saja dan jangan menengok konsep yang lain supaya tidak ragu-ragu lagi","Kerjakan keduanya sepenuhnya sampai selesai dengan lengkap, lalu bandingkan hasil akhir keduanya"],answer:0,explain:"Membandingkan dua prototipe kasar mengeluarkan alasan & preferensi pengguna yang tidak muncul dari satu konsep sendirian.",hint:"Prototipe keduanya & bandingkan, atau pilih berdasar selera?"},
{n:56,type:"tf",micro:"Kegagalan uji itu berharga",q:"Benar atau Salah: Kalau prototipe kita membingungkan pengguna saat diuji, itu hasil yang berguna, kita belajar apa yang perlu diperbaiki sebelum membuat versi sungguhan.",answer:true,explain:"Menemukan kebingungan pada prototipe kertas jauh lebih murah daripada menemukannya setelah solusi dibuat & diluncurkan.",hint:"Berguna untuk perbaikan, atau tanda kegagalan yang memalukan?"},
{n:57,type:"mcq",micro:"Menyeimbangkan waktu antar tahap",q:"Kesalahan pembagian waktu yang umum dalam proyek berpikir desain pemula:",options:["Menguji prototipe dengan beberapa orang pengguna sebelum memutuskan solusi mana yang akan dipakai","Menghabiskan hampir semua waktu membuat solusi & hampir tidak ada waktu untuk empati & uji","Menghabiskan cukup waktu untuk memahami pengguna sebelum mulai membuat solusi apa pun juga"],answer:1,explain:"Tergesa melewati empati & uji menghasilkan solusi rapi yang meleset. Tahap-tahap 'memahami' & 'belajar' sama pentingnya dengan 'membuat'.",hint:"Semua waktu untuk membuat, atau seimbang dengan memahami & menguji?"},
{n:58,type:"mcq",micro:"Umpan balik yang menuju perbaikan",q:"Setelah menguji, cara mengubah temuan jadi perbaikan:",options:["Perbaiki setiap komentar tunggal dari pengguna tanpa memilah mana yang penting & mana yang tidak","Abaikan temuan yang tidak kita sukai & hanya perbaiki temuan yang sesuai dengan keinginan tim","Kelompokkan masalah, prioritaskan yang dialami banyak pengguna & paling menghambat, perbaiki beberapa, uji lagi"],answer:2,explain:"Pola masalah (dialami 4 dari 5) lebih penting daripada preferensi unik satu orang. Perbaiki bertahap & uji ulang.",hint:"Kelompokkan & prioritaskan pola, atau ikuti tiap komentar / abaikan yang tak disuka?"},
{n:59,type:"mcq",micro:"Kapan proses cukup",q:"Sebuah siklus berpikir desain 'cukup' untuk sekarang ketika...",options:["Solusi menjawab kebutuhan inti pengguna, uji terakhir tidak lagi mengungkap masalah besar, & waktu/sumber daya perlu dialihkan","Setiap detail kecil dari solusi sudah sempurna dan tidak ada satu pun yang masih bisa diperbaiki","Semua orang di dunia yang mungkin memakai solusi itu sudah diwawancarai satu per satu oleh tim"],answer:0,explain:"Berpikir desain bisa berputar selamanya. Titik 'cukup' adalah saat solusi bekerja untuk kebutuhan inti & imbal hasil perbaikan mengecil.",hint:"Kebutuhan inti terpenuhi & masalah besar habis, atau setiap detail sempurna?"},
{n:60,type:"open",micro:"Jalankan mini-proyek desain",q:"Pilih satu masalah nyata yang menyangkut sekelompok orang di sekitarmu. Rancang mini-proyek berpikir desain: (a) rencana empati (siapa yang diajak bicara/diamati & 3 pertanyaan), (b) pernyataan masalah sementara, (c) 1 pertanyaan 'bagaimana caranya kita' + 3 ide solusi berbeda, (d) 1 ide terpilih + prototipe kasarnya + apa yang akan diuji, (e) rencana uji (siapa, tugas, yang diamati), (f) bagaimana kamu akan memutuskan langkah berikutnya berdasar hasil uji.",explain:"Jawaban baik: rencana empati yang melibatkan kedua kelompok pengguna (yang berlebih & yang kurang), pernyataan masalah bebas solusi, pertanyaan 'bagaimana caranya kita' yang memuat batasan penting (higienis, tidak mempermalukan), 3 ide yang benar-benar berbeda, prototipe kasar dengan hal spesifik yang diuji, rencana uji yang mengamati perilaku & perasaan, & keputusan bercabang yang bisa mengirim kembali ke tahap sebelumnya.",hint:"Bagian (f) yang membedakan berpikir desain dari sekadar 'membuat solusi', tunjukkan bahwa hasil uji bisa mengirimmu kembali ke empati atau definisi, bukan hanya 'perbaiki sedikit'.",sample:"Masalah: banyak siswa membuang makanan bekal yang tidak habis, & sebagian siswa lain justru tidak membawa/tidak punya bekal. (a) Empati: bicara dengan 6 siswa (3 yang sering menyisakan bekal, 3 yang jarang bawa bekal) & amati meja saat istirahat 2 hari. Pertanyaan: 'Ceritakan bekalmu hari ini, siapa yang menyiapkan & apa yang biasanya tersisa & kenapa?', 'Kalau kamu tidak bawa bekal, biasanya kamu makan apa saat istirahat?', 'Bagaimana perasaanmu melihat makanan dibuang / melihat teman tidak makan?' (b) Pernyataan masalah sementara: 'Sebagian siswa punya kelebihan makanan utuh yang terbuang, sementara sebagian lain tidak makan siang, karena tidak ada cara aman & tidak memalukan untuk berbagi.' (c) Bagaimana caranya kita: 'Bagaimana caranya kita membuat makanan berlebih sampai ke siswa yang membutuhkan, dengan cara yang higienis & tidak mempermalukan siapa pun?' Tiga ide: (1) rak 'berbagi' untuk makanan kemasan tertutup & utuh; (2) 'kotak amal snack' yang diisi sukarela & bisa diambil diam-diam; (3) sistem 'teman makan' berpasangan agar berbagi terasa biasa. (d) Ide terpilih: rak berbagi (ide 1). Prototipe: satu rak kardus berlabel di sudut kelas + aturan singkat + guru piket mengecek. Yang diuji: apakah siswa mau menaruh (memberi) & apakah yang butuh mau mengambil tanpa malu. (e) Uji: jalankan 4 hari di satu kelas; amati jumlah barang masuk & keluar tiap hari; tanya 4 siswa (termasuk yang biasanya tidak bawa bekal) bagaimana perasaan mereka soal mengambil dari rak. (f) Keputusan: jika ada aliran masuk & keluar yang cukup & siswa merasa nyaman, LANJUT ke lebih banyak kelas dengan aturan higiene yang lebih rapi. Jika banyak yang menaruh tapi sedikit yang berani mengambil, kembali ke tahap DEFINISI, mungkin masalah 'malu' lebih besar dari dugaan & ide 'teman makan' atau pengambilan yang lebih privat lebih cocok. Jika hampir tidak ada yang menaruh, kembali ke EMPATI untuk memahami kenapa."},
{n:61,type:"mcq",micro:"Jebakan: melompat ke solusi",q:"Tanda tim melompat ke solusi terlalu cepat:",options:["Membuat peta perjalanan pengguna yang menggambarkan langkah dan perasaan mereka dari awal sampai akhir","Diskusi langsung tentang 'aplikasi apa' atau 'alat apa' sebelum jelas siapa penggunanya & apa kesulitan mereka","Berdiskusi tentang siapa saja yang akan diwawancarai dan pertanyaan apa yang akan ditanyakan nanti"],answer:1,explain:"Kalau percakapan pertama tentang bentuk solusi, bukan tentang orang & masalah, itu tanda tahap empati & definisi dilewati.",hint:"Langsung bahas bentuk solusi, atau bahas pengguna & masalah dulu?"},
{n:62,type:"mcq",micro:"Jebakan: mendesain untuk diri sendiri",q:"'Aku sendiri akan memakai ini, jadi pasti bagus' berbahaya karena...",options:["Perancang selalu paling tahu apa yang dibutuhkan oleh semua pengguna sehingga tidak perlu bertanya","Tidak berbahaya sama sekali, sebab memakai sendiri sudah termasuk pengujian yang cukup untuk solusinya","Perancang sering tidak mewakili pengguna sebenarnya, kebiasaan, pengetahuan, & konteks kita berbeda dari mereka"],answer:2,explain:"Kamu tahu 'maksudnya', kamu terbiasa dengan istilahnya, kamu tidak dalam situasi terburu-buru pengguna. Uji dengan orang lain tetap perlu.",hint:"Perancang sering berbeda dari pengguna, atau selalu mewakili?"},
{n:63,type:"mcq",micro:"Jebakan: mengabaikan konteks",q:"Solusi 'kartu antre digital di HP' bisa gagal kalau...",options:["Sebagian besar pengguna di konteks itu tidak punya HP atau sinyal, konteks nyata diabaikan","Terlihat modern","Perancangnya suka teknologi"],answer:0,explain:"Solusi harus cocok dengan alat, keterampilan, & keterbatasan nyata penggunanya, bukan dengan dunia ideal perancang.",hint:"Konteks nyata pengguna diabaikan, atau solusi terlihat modern?"},
{n:64,type:"tf",micro:"Aksesibilitas",q:"Benar atau Salah: Aksesibilitas (orang dengan kemampuan penglihatan, pendengaran, gerak, bahasa yang berbeda) sebaiknya dipikirkan hanya di akhir, sebagai tambahan setelah solusi utama jadi.",answer:false,explain:"Sebaliknya, memikirkan aksesibilitas sejak awal biasanya menghasilkan solusi yang lebih baik untuk semua orang & lebih murah daripada menambahkannya belakangan.",hint:"Sejak awal, atau tambahan di akhir?"},
{n:65,type:"mcq",micro:"Etika desain: siapa yang diuntungkan & dirugikan",q:"Sebelum menyelesaikan sebuah solusi, pertanyaan etis yang penting:",options:["'Apakah aku sendiri merasa bangga dengan hasil karyaku ini dibandingkan hasil karya teman-teman?'","'Siapa yang diuntungkan solusi ini, & adakah pihak yang justru dirugikan atau tersisih olehnya?'","'Apakah solusi ini terlihat keren & modern sehingga juri dan penonton akan memberi nilai yang tinggi?'"],answer:1,explain:"Solusi yang membantu satu kelompok kadang menyulitkan kelompok lain. Memeriksa ini menjaga desain tetap adil.",hint:"Periksa siapa diuntungkan & dirugikan, atau apakah terlihat keren?"},
{n:66,type:"mcq",micro:"Etika: persetujuan saat riset",q:"Saat mengamati atau mewawancarai orang untuk memahami masalah, yang harus dijaga:",options:["Rahasiakan tujuan agar reaksinya alami","Rekam diam-diam","Jujur tentang tujuannya, minta izin, hargai waktu & privasi mereka, & jangan memakai cerita mereka dengan cara yang merugikan"],answer:2,explain:"Melibatkan orang berarti bertanggung jawab pada mereka: kejujuran, izin, & menjaga apa yang mereka bagikan.",hint:"Jujur & minta izin, atau rahasiakan / rekam diam-diam?"},
{n:67,type:"mcq",micro:"Desain yang memaksa vs memberdayakan",q:"Beda desain yang 'memaksa perilaku' dengan yang 'memberdayakan pilihan':",options:["Memaksa: menghilangkan pilihan orang demi hasil yang perancang inginkan. Memberdayakan: memudahkan pilihan yang baik sambil tetap menghormati kebebasan","Keduanya sama","Memaksa selalu lebih efektif & lebih baik"],answer:0,explain:"Desain yang etis cenderung membuat hal baik jadi mudah & jelas, bukan menjebak atau menekan orang tanpa mereka sadari.",hint:"Menghormati kebebasan sambil memudahkan pilihan baik, atau menjebak?"},
{n:68,type:"tf",micro:"Umpan balik pengguna vs keinginan perancang",q:"Benar atau Salah: Ketika hasil uji jelas menunjukkan solusi tidak bekerja untuk pengguna, tapi perancang sangat menyukainya, perancang sebaiknya mendahulukan temuan pengguna.",answer:true,explain:"Berpusat pada manusia berarti kebutuhan pengguna mengalahkan kesenangan perancang. Kalau tidak, prosesnya sekadar formalitas.",hint:"Dahulukan temuan pengguna, atau kesukaan perancang?"},
{n:69,type:"mcq",micro:"Menghindari 'solusi mencari masalah'",q:"'Solusi mencari masalah' terjadi ketika...",options:["Kita menguji prototipe kepada pengguna lalu memperbaikinya berdasarkan temuan yang dikumpulkan","Kita punya ide/teknologi yang kita suka & memaksa mencari masalah agar bisa memakainya, bukan sebaliknya","Kita menemukan masalah nyata dari pengamatan lalu baru mencari solusi yang paling cocok untuknya"],answer:1,explain:"Berpikir desain membalik ini: masalah & kebutuhan manusia dulu, solusi menyusul. Bukan 'aku mau pakai QR code, di mana bisa kupasang?'.",hint:"Ide dulu lalu cari masalah, atau masalah dulu lalu cari solusi?"},
{n:70,type:"tf",micro:"Definisi ulang itu kemajuan",q:"Benar atau Salah: Menemukan di tengah proyek bahwa pernyataan masalah awal kurang tepat, lalu memperbaikinya, adalah tanda proses berjalan baik, bukan tanda gagal.",answer:true,explain:"Pemahaman berkembang. Berani memperbaiki arah berdasarkan pemahaman baru adalah inti berpikir desain, bukan kegagalan.",hint:"Tanda proses sehat, atau tanda gagal?"},
{n:71,type:"mcq",micro:"Menyeimbangkan suara pengguna yang beragam",q:"Pengguna A butuh solusi yang sederhana; pengguna B butuh yang lengkap. Pendekatan desain:",options:["Ikuti yang paling keras bersuara","Buang keduanya","Cari solusi dengan inti sederhana untuk semua, dengan bagian lanjutan bagi yang membutuhkan; atau putuskan target utama dengan sadar"],answer:2,explain:"Kebutuhan beragam butuh solusi berlapis atau pilihan sadar tentang siapa yang dilayani utama, bukan kompromi yang mengecewakan semua.",hint:"Inti sederhana + lanjutan opsional / target sadar, atau ikut yang keras?"},
{n:72,type:"mcq",micro:"Desain & keberlanjutan",q:"Selain 'apakah bekerja sekarang', pertanyaan desain jangka panjang:",options:["'Apakah solusi ini bisa dirawat & bertahan setelah kami yang membuatnya tidak lagi mengurusnya?'","'Apakah solusi ini akan menjadi viral & dibicarakan banyak orang di media sosial dalam waktu singkat?'","'Apakah proyek ini selesai tepat waktu sehingga kami bisa mengumpulkannya sebelum batas yang ditentukan?'"],answer:0,explain:"Banyak solusi bagus mati karena tidak ada yang merawatnya. Desain yang baik memikirkan siapa yang akan menjaganya berjalan.",hint:"Bisa dirawat & bertahan, atau sekadar viral?"},
{n:73,type:"mcq",micro:"Ketika data empati sedikit",q:"Kamu hanya sempat mewawancarai 2 orang & keduanya berkata hal berbeda. Sikap yang tepat:",options:["Berhenti saja dari proyek ini karena data wawancaranya bertentangan sehingga tidak bisa dipakai","Perlakukan pemahamanmu sebagai sementara & rawan salah; cari kesempatan bicara dengan lebih banyak orang sebelum berkomitmen besar","Anggap salah satu dari mereka pasti mewakili semua orang lainnya, lalu pilih jawaban yang paling masuk akal"],answer:1,explain:"Dua titik data yang bertentangan berarti kamu belum tahu polanya. Sadari keterbatasan & jangan bangun sesuatu yang besar di atasnya.",hint:"Perlakukan sebagai sementara & cari lebih banyak, atau pilih salah satu / berhenti?"},
{n:74,type:"mcq",micro:"Desain & rendah hati",q:"Sikap yang menyertai berpikir desain yang baik:",options:["Keyakinan bahwa perancang selalu paling tahu apa yang dibutuhkan orang sehingga tidak perlu mengecek","Ketidakpedulian pada hasil uji karena perancang sudah yakin solusinya benar sejak pertama kali dibuat","Kerendahan hati: 'aku mungkin salah tentang apa yang dibutuhkan orang, mari kita cek dengan mereka'"],answer:2,explain:"Berpikir desain adalah cara terstruktur untuk mengatakan 'aku tidak tahu pasti, ayo cari tahu bersama pengguna'.",hint:"Sadar bisa salah & cek dengan pengguna, atau merasa paling tahu?"},
{n:75,type:"order",micro:"Memeriksa etika sebuah solusi",q:"Urutkan langkah memeriksa apakah solusi desainmu adil & bertanggung jawab.",items:["Daftar semua kelompok yang akan terpengaruh solusi ini","Untuk tiap kelompok, tanya: apa yang mereka dapat & apa yang mungkin mereka kehilangan atau alami sebagai kesulitan","Periksa apakah ada kelompok yang tersisih atau tidak bisa memakainya (aksesibilitas)","Sesuaikan solusi untuk mengurangi kerugian & ketersisihan, atau jelaskan trade-off dengan terbuka"],answer:[0,1,2,3],explain:"Daftar terdampak → untung & rugi tiap kelompok → cek ketersisihan → perbaiki atau jelaskan trade-off. Desain yang adil memeriksa dampaknya pada semua, bukan hanya pengguna utama.",hint:"Memeriksa aksesibilitas sebelum atau sesudah memetakan untung-rugi tiap kelompok?"},
{n:76,type:"tf",micro:"Solusi sederhana sering lebih baik",q:"Benar atau Salah: Dalam berpikir desain, solusi yang paling lengkap & mencoba melakukan segalanya hampir selalu lebih baik daripada solusi sederhana.",answer:false,explain:"Sebaliknya, solusi paling sederhana yang benar-benar menyelesaikan kebutuhan inti sering lebih baik: lebih mudah dibuat, dipahami pengguna, dirawat, & lebih sedikit yang bisa rusak. Kelengkapan sering menjadi beban.",hint:"Sederhana yang cukup, atau rumit yang serba bisa?"},
{n:77,type:"mcq",micro:"Berpikir desain vs mengikuti selera guru/juri",q:"Kalau proyek dinilai oleh juri, godaan yang perlu diwaspadai:",options:["Merancang untuk mengesankan juri alih-alih membantu pengguna sebenarnya","Menguji solusi dengan pengguna nyata secara berkala supaya penilaian juri didasarkan pada bukti","Membuat pernyataan masalah yang jelas & mudah dipahami supaya juri langsung mengerti tujuan proyek"],answer:0,explain:"Solusi yang benar-benar membantu pengguna biasanya juga meyakinkan juri. Merancang 'untuk juri' menghasilkan sesuatu yang mengilap tapi kosong.",hint:"Merancang untuk mengesankan juri, atau untuk membantu pengguna?"},
{n:78,type:"mcq",micro:"Menangani solusi yang merugikan sebagian pihak",q:"Solusi terbaikmu jelas membantu mayoritas tapi menyulitkan satu kelompok kecil. Sikap yang bertanggung jawab:",options:["Batalkan seluruh solusi itu karena tidak mungkin menyenangkan semua orang dalam waktu yang sama","Cari cara mengurangi kesulitan kelompok itu; kalau tidak sepenuhnya bisa, akui trade-off itu secara terbuka & sediakan bantuan bagi mereka","Sembunyikan dampak buruknya pada kelompok kecil itu supaya solusi tetap diterima oleh banyak orang"],answer:1,explain:"Kadang tidak ada solusi yang sempurna untuk semua. Yang etis: transparan tentang trade-off & upayakan peringanan, bukan menyembunyikan.",hint:"Kurangi kesulitan & akui trade-off terbuka, atau sembunyikan / batalkan?"},
{n:79,type:"mcq",micro:"Berpikir desain sebagai kebiasaan",q:"Menjadikan berpikir desain kebiasaan berarti, sebelum membuat apa pun untuk orang lain, secara refleks bertanya...",options:["'Bagaimana caranya supaya hasil buatanku ini terlihat paling bagus & paling mengesankan bagi banyak orang?'","'Berapa lama waktu yang kupunya, dan apakah aku masih sempat menyelesaikannya sebelum batas tenggat?'","'Siapa yang akan memakai ini? Apa yang benar-benar mereka butuhkan? Sudahkah aku cek dengan mereka?'"],answer:2,explain:"Refleks bertanya 'untuk siapa & apa kebutuhannya' membedakan sesuatu yang benar-benar berguna dari sesuatu yang sekadar dibuat.",hint:"Untuk siapa & apa kebutuhannya, atau bagaimana agar terlihat bagus?"},
{n:80,type:"open",micro:"Periksa etika & aksesibilitas sebuah solusi",q:"Ambil sebuah solusi (milikmu atau yang kamu amati, mis. 'sistem antre pakai nomor', 'aplikasi absen', 'jam malam belajar bersama'). Analisis: (a) daftar minimal 3 kelompok yang terpengaruh, (b) untuk masing-masing, apa yang mereka dapat & apa yang mungkin menyulitkan mereka, (c) adakah orang yang tidak bisa memakainya (akses, alat, kemampuan, bahasa) dan bagaimana memperbaikinya, (d) satu trade-off yang menurutmu tetap ada & bagaimana kamu akan menjelaskannya dengan jujur.",explain:"Jawaban baik: minimal 3 kelompok yang benar-benar berbeda posisinya (termasuk yang mungkin dirugikan), analisis untung-rugi yang jujur untuk masing-masing, identifikasi kelompok yang tersisih secara akses/kemampuan dengan perbaikan konkret & setara (bukan sekadar 'lapor ke guru'), & satu trade-off yang diakui tetap ada dengan cara menjelaskannya yang jujur & tidak mempermalukan siapa pun.",hint:"Bagian (c) kuncinya, perbaikan untuk yang tersisih harus benar-benar setara & tidak mempermalukan, bukan solusi kelas dua.",sample:"Solusi: aplikasi absensi lewat siswa memindai QR code di kelas dengan HP masing-masing. (a) Kelompok terpengaruh: (1) siswa yang punya HP & sinyal bagus, (2) siswa yang tidak punya HP atau HP-nya sering bermasalah, (3) guru, (4) wali murid yang ingin memantau kehadiran. (b) Untung & sulit: Kelompok 1 dapat proses cepat, tidak perlu antre tanda tangan; kesulitannya kecil, mungkin lupa bawa HP. Kelompok 2 justru dirugikan, harus menumpang HP teman atau lapor manual, bisa merasa berbeda/malu, & rawan dianggap 'bolos' kalau prosesnya lambat. Guru dapat rekap otomatis & hemat waktu, tapi harus menangani kasus yang gagal scan & memastikan tidak ada titip-absen. Wali murid dapat info lebih cepat, tapi bisa cemas berlebihan kalau ada kesalahan teknis yang terlihat seperti anak tidak masuk. (c) Yang tidak bisa memakai: siswa tanpa HP, siswa dengan gangguan penglihatan yang sulit memindai, & mungkin siswa yang HP-nya tidak mendukung. Perbaikan: sediakan jalur manual yang setara & tidak memalukan (guru menandai lewat daftar biasa dalam hitungan detik, bukan siswa harus melapor ke depan kelas), pastikan tampilannya bisa dibaca layar pembaca, & sediakan beberapa 'HP kelas' cadangan. (d) Trade-off yang tetap ada: sistem ini mempercepat absensi untuk mayoritas tapi selalu butuh jalur manual untuk sebagian siswa, jadi guru tetap harus mengelola dua cara. Aku akan menjelaskan ini secara terbuka ke guru & kelas: 'Sistem QR untuk yang bisa, jalur daftar biasa untuk yang tidak, keduanya sama sahnya & tidak ada yang perlu merasa berbeda. Guru akan tetap mengecek keduanya.'"},
{n:81,type:"mcq",micro:"Skenario: tim ingin langsung membuat",q:"Kelompokmu bersemangat & ingin langsung membuat solusi tanpa wawancara. Cara mengajak berpikir desain:",options:["Usulkan wawancara singkat 3-4 orang besok (30 menit total) & tunjukkan bahwa ini bisa mencegah membuat hal yang salah","Ikut saja pada teman-teman karena mayoritas anggota kelompok ingin langsung mengerjakan solusinya","Memaksa mereka mewawancarai pengguna sekarang juga tanpa menjelaskan alasan di balik usulanmu itu"],answer:0,explain:"Menawarkan langkah empati yang kecil & cepat, sambil menghubungkannya dengan menghindari kerja sia-sia, lebih meyakinkan daripada ceramah.",hint:"Tawarkan empati singkat + alasannya, atau ikut / memaksa?"},
{n:82,type:"mcq",micro:"Skenario: pengguna minta hal yang tidak mungkin",q:"Saat wawancara, pengguna minta sesuatu yang jelas di luar kemampuan kelompok (mis. 'AC di setiap sudut lapangan'). Sikap:",options:["Janjikan saja kepada pengguna sesuatu yang tidak bisa kamu penuhi supaya mereka senang dan mau bicara","Gali kebutuhan di baliknya ('kepanasan saat kegiatan siang') & cari solusi yang mungkin (jadwal, peneduh, air minum)","Katakan kepada pengguna bahwa permintaannya bodoh & mustahil dipenuhi supaya mereka tidak meminta lagi"],answer:1,explain:"Permintaan yang tidak mungkin tetap mengandung kebutuhan nyata. Tugas perancang menemukan & memenuhi kebutuhan itu dengan cara yang layak.",hint:"Gali kebutuhan di baliknya, atau tolak kasar / janji palsu?"},
{n:83,type:"mcq",micro:"Skenario: hasil uji mengecewakan",q:"Prototipe yang kelompok sukai ternyata membingungkan 4 dari 5 penguji. Langkah berpikir desain:",options:["Salahkan para penguji karena kurang pintar memahami prototipe yang sudah dibuat dengan susah payah","Pakai prototipe apa adanya karena kelompok sudah menyukainya dan tidak ingin mengubah lagi sedikit pun","Terima temuannya, cari pola kebingungannya, & putuskan: perbaiki bagian itu, atau kembali ke definisi masalah bila kebingungannya mendasar"],answer:2,explain:"Kebingungan pengguna adalah data tentang desain, bukan tentang pengguna. Responsnya: pelajari & perbaiki atau redefinisi.",hint:"Pelajari pola & perbaiki/redefinisi, atau salahkan penguji / abaikan?"},
{n:84,type:"mcq",micro:"Skenario: waktu habis di tahap empati",q:"Kamu terlalu lama di tahap empati & waktu untuk membuat & menguji tinggal sedikit. Sikap seimbang:",options:["Rangkum cepat wawasan yang sudah ada, buat pernyataan masalah, & sisakan waktu untuk minimal satu putaran prototipe & uji","Terus berempati sampai benar-benar yakin sepenuhnya, walau waktu untuk membuat dan menguji sudah habis","Lewati tahap prototipe & uji, langsung buat versi final saja supaya selesai tepat pada waktunya"],answer:0,explain:"Semua tahap butuh porsi. Empati tanpa batas sama merugikannya dengan melewatinya, keseimbangan & menyisakan waktu untuk uji itu penting.",hint:"Rangkum & sisakan waktu untuk uji, atau berempati tanpa henti / lewati uji?"},
{n:85,type:"tf",micro:"Solusi terbaik sering sederhana & tak terduga",q:"Benar atau Salah: Solusi desain terbaik untuk sebuah masalah selalu yang paling canggih secara teknologi.",answer:false,explain:"Sebaliknya, solusi terbaik kadang justru yang paling pas dengan kebutuhan & konteks nyata pengguna, meski sederhana, sebuah papan tulis di lokasi tepat bisa mengalahkan aplikasi mahal.",hint:"Yang paling pas dengan kebutuhan & konteks, atau yang paling canggih?"},
{n:86,type:"mcq",micro:"Skenario: dua kelompok pengguna bertentangan",q:"Guru ingin sistem yang ketat & tercatat; siswa ingin yang cepat & tidak ribet. Pendekatan desain:",options:["Selalu menangkan keinginan siswa karena jumlah siswa jauh lebih banyak daripada jumlah guru","Cari solusi yang memenuhi kebutuhan inti keduanya (tercatat otomatis TAPI cepat bagi siswa), uji dengan keduanya","Selalu menangkan keinginan guru karena guru lebih berkuasa dan lebih berpengalaman dalam hal aturan"],answer:1,explain:"Di balik posisi yang bertentangan sering ada kebutuhan yang bisa didamaikan. Solusi yang melayani kebutuhan inti kedua pihak lebih tahan lama.",hint:"Penuhi kebutuhan inti keduanya, atau menangkan salah satu?"},
{n:87,type:"mcq",micro:"Skenario: solusi berhasil di uji, sulit dirawat",q:"Prototipe layanan berhasil, tapi butuh 3 orang mengurusnya tiap hari & tidak ada yang bersedia jangka panjang. Sikap desain:",options:["Jalankan saja layanan itu apa adanya dan berharap nanti akan ada orang yang mau mengurusnya setiap hari","Batalkan prototipe itu tanpa mencari versi yang lebih ringan, karena tidak ada yang bersedia mengurusnya","Rancang ulang agar lebih sederhana & bisa dijalankan dengan tenaga yang realistis tersedia, atau siapkan sistem giliran yang jelas"],answer:2,explain:"Solusi yang tidak bisa dirawat akan mati. 'Bisa dijalankan dengan sumber daya yang benar-benar ada' adalah bagian dari desain yang baik.",hint:"Sederhanakan agar bisa dirawat, atau jalankan & berharap / batalkan?"},
{n:88,type:"mcq",micro:"Skenario: kamu bukan pengguna",q:"Kamu merancang sesuatu untuk siswa tunanetra & kamu sendiri bisa melihat. Langkah paling penting:",options:["Libatkan siswa tunanetra sebagai mitra sepanjang proses, uji setiap tahap bersama mereka, jangan mengandalkan bayanganmu tentang kebutuhan mereka","Baca beberapa artikel tentang tunanetra lalu rancang sendiri solusinya berdasarkan apa yang kamu baca","Buat solusinya sendiri sampai selesai lalu minta persetujuan mereka hanya di bagian akhir proyek"],answer:0,explain:"Untuk kelompok yang pengalamannya jauh dari kita, keterlibatan langsung mereka bukan pelengkap, itu inti prosesnya.",hint:"Libatkan sebagai mitra sepanjang proses, atau rancang sendiri lalu minta setuju?"},
{n:89,type:"mcq",micro:"Skenario: proyek dinilai dari presentasi",q:"Proyekmu akan dipresentasikan & dinilai. Cara menjaga berpikir desain tetap jujur:",options:["Fokus hanya pada tampilan solusi akhir yang indah supaya juri langsung terkesan pada penampilannya","Tunjukkan proses sebenarnya: kutipan pengguna, pernyataan masalah, ide yang diuji & yang gugur, temuan uji, & bagaimana solusi berubah","Sembunyikan semua bagian yang gagal & tampilkan seolah-olah seluruh prosesnya berjalan mulus tanpa masalah"],answer:1,explain:"Proses yang jujur, termasuk yang tidak berhasil & pelajarannya, biasanya lebih meyakinkan & mencerminkan berpikir desain yang sebenarnya.",hint:"Tunjukkan proses jujur termasuk yang gagal, atau tampilkan seolah mulus?"},
{n:90,type:"order",micro:"Proyek desain penuh dalam sebulan",q:"Urutkan fase proyek berpikir desain sebulan untuk masalah sekolah nyata.",items:["Minggu 1: empati, wawancara & amati pengguna beragam, sintesis jadi wawasan & pernyataan masalah","Minggu 2: curah gagasan banyak solusi, saring dengan kriteria, pilih 1-2","Minggu 3: buat prototipe, uji ke pengguna, kelompokkan temuan, perbaiki (atau redefinisi masalah)","Minggu 4: putaran uji kedua, finalisasi solusi yang bisa dirawat, siapkan dokumentasi proses & serah terima"],answer:[0,1,2,3],explain:"Empati & definisi → ide & pilih → prototipe, uji, perbaiki → uji lagi & serah terima. Dua putaran uji & fokus pada solusi yang bisa dirawat.",hint:"Curah gagasan sebelum atau sesudah sintesis pernyataan masalah?"},
{n:91,type:"mcq",micro:"Skenario: menemukan masalah yang lebih penting",q:"Di tengah proyek 'memperbaiki papan pengumuman', wawancara mengungkap masalah yang jauh lebih penting: siswa tidak tahu ke mana harus melapor kalau ada masalah. Sikap:",options:["Abaikan temuan itu karena bukan topik yang ditugaskan kepada kelompok sejak awal proyek dimulai","Kerjakan keduanya sekaligus tanpa membahasnya dengan guru atau kelompok supaya tidak ada yang ribut","Bawa temuan ini ke kelompok & guru pembimbing, pertimbangkan mengalihkan fokus proyek ke masalah yang lebih penting itu"],answer:2,explain:"Berpikir desain menghargai penemuan bahwa 'masalah yang benar' berbeda dari yang diasumsikan. Diskusikan sebelum berbelok, tapi jangan abaikan temuan penting.",hint:"Bawa ke kelompok & pertimbangkan mengalihkan fokus, atau abaikan?"},
{n:92,type:"tf",micro:"Berpikir desain butuh mendengar sungguh-sungguh",q:"Benar atau Salah: Inti berpikir desain bukan teknik atau alat tertentu, melainkan sikap sungguh-sungguh mendengar & memahami orang sebelum & selama membuat solusi untuk mereka.",answer:true,explain:"Peta perjalanan, persona, & sticky notes adalah alat. Yang membuat berpikir desain bekerja adalah niat jujur untuk memahami & melayani kebutuhan nyata.",hint:"Sikap mendengar & memahami, atau sekadar teknik & alat?"},
{n:93,type:"mcq",micro:"Skenario: solusi bagus tapi tidak dipakai",q:"Solusi kelompokmu diluncurkan tapi hampir tidak ada yang memakainya. Langkah berpikir desain:",options:["Kembali ke pengguna: cari tahu kenapa, apakah tidak tahu, tidak butuh, terlalu ribet, atau tidak percaya, lalu perbaiki berdasar temuan","Simpulkan saja bahwa orang-orang di sekolah itu malas mencoba hal baru sehingga solusinya tidak salah","Paksa mereka memakainya lewat aturan resmi supaya jumlah pengguna naik dan proyek terlihat berhasil"],answer:0,explain:"Ketiadaan pemakaian adalah data. Bisa soal kesadaran, kebutuhan, kemudahan, atau kepercayaan, selidiki sebelum menyimpulkan.",hint:"Selidiki kenapa tidak dipakai, atau salahkan orang / paksa?"},
{n:94,type:"mcq",micro:"Skenario: menyeimbangkan idealisme & kenyataan",q:"Solusi 'ideal' hasil desainmu butuh dana & izin yang belum ada. Langkah realistis:",options:["Jalankan saja versi idealnya secara diam-diam tanpa izin, lalu minta maaf kalau ternyata ada yang keberatan","Buat versi paling sederhana yang tetap menjawab kebutuhan inti & bisa dijalankan sekarang, sambil memakai buktinya untuk mengusulkan versi lebih besar nanti","Menyerah saja karena versi ideal itu tidak mungkin diwujudkan dan tidak ada gunanya mencoba versi lain"],answer:1,explain:"Berpikir desain praktis: mulai dari yang mungkin sekarang, tunjukkan nilainya, lalu perbesar. Bukti dari versi kecil adalah alat persuasi terkuat.",hint:"Versi sederhana yang bisa jalan sekarang, atau menyerah / diam-diam?"},
{n:95,type:"tf",micro:"Proses bisa singkat atau panjang",q:"Benar atau Salah: Berpikir desain bisa dilakukan dalam skala besar (proyek berbulan-bulan) atau kecil (satu jam untuk memutuskan cara menata sudut baca), selama urutan pahami-rumuskan-cari ide-coba-pelajari dijaga.",answer:true,explain:"Yang penting adalah polanya, bukan lamanya. Bahkan keputusan kecil jadi lebih baik bila kita berempati sebentar & menguji sebelum menetapkan.",hint:"Bisa skala besar & kecil, atau hanya proyek panjang?"},
{n:96,type:"mcq",micro:"Skenario: pengguna berubah pikiran",q:"Pengguna yang di tahap empati bilang butuh A, di tahap uji ternyata lebih menyukai B. Sikap:",options:["Anggap pengguna itu tidak konsisten & abaikan saja ucapan mereka, karena perilaku mereka tidak bisa dipercaya","Tetap buat A saja karena itu yang pertama kali mereka katakan, bukan yang mereka pilih saat mencoba","Wajar, kebutuhan & pemahaman berkembang saat orang melihat sesuatu yang konkret; ikuti bukti dari uji & gali kenapa berubah"],answer:2,explain:"Orang sering baru tahu yang mereka butuhkan setelah melihat pilihan nyata. Prototipe membuat kebutuhan lebih jelas, & itu gunanya.",hint:"Ikuti bukti uji & gali kenapa, atau abaikan / tetap A?"},
{n:97,type:"mcq",micro:"Menilai kualitas proses desainmu",q:"Tanda kamu menjalankan berpikir desain dengan baik:",options:["Kamu bicara dengan pengguna nyata, pernyataan masalahmu bebas solusi, kamu punya beberapa ide sebelum memilih, kamu menguji prototipe & idemu berubah karena temuan","Kamu sudah punya satu ide yang bagus sejak awal & langsung membuatnya tanpa perlu menimbang ide lain","Kamu tidak pernah menunjukkan apa pun kepada pengguna supaya mereka terkejut ketika solusinya selesai"],answer:0,explain:"Proses yang sehat: berbasis pengguna, masalah dulu, banyak ide, prototipe diuji, & responsif terhadap temuan.",hint:"Berbasis pengguna & responsif temuan, atau satu ide langsung dibuat?"},
{n:98,type:"mcq",micro:"Berpikir desain di kehidupan",q:"Pola berpikir desain berguna di luar proyek untuk...",options:["Tidak relevan di kehidupan sehari-hari, sebab berpikir desain hanya cocok untuk perusahaan dan pabrik besar","Merencanakan hadiah (pahami yang diberi), menata kamar (untuk kebiasaanmu), menyusun aturan keluarga (libatkan semua), membantu teman (pahami kebutuhannya dulu)","Hanya untuk proyek sekolah & pembuatan produk, sedangkan urusan pribadi memakai cara yang lain lagi"],answer:1,explain:"Kapan pun kita membuat sesuatu untuk dipakai orang (termasuk diri sendiri), memahami kebutuhan dulu & mencoba sebelum menetapkan menghasilkan hasil yang lebih baik.",hint:"Berguna untuk banyak hal, atau hanya proyek sekolah?"},
{n:99,type:"mcq",micro:"Inti keterampilan",q:"Inti dari berpikir desain:",options:["Buat solusi yang paling canggih secepat mungkin lalu pasarkan, karena pengguna akan menyukai teknologi yang paling baru","Rancang dengan sempurna di atas kertas lebih dulu, lalu bangun sekali jadi tanpa perlu diuji atau diperbaiki lagi","Pahami orang yang punya masalah secara nyata, rumuskan masalah yang tepat (bukan solusi), cari banyak ide, buat & uji versi kasar dengan mereka, & perbaiki, berputar sampai solusi benar-benar membantu"],answer:2,explain:"Berpusat pada manusia, masalah sebelum solusi, banyak ide, prototipe & uji, iterasi. Semuanya menjaga solusi menempel pada kebutuhan nyata.",hint:"Pahami orang - rumuskan masalah - ide - prototipe & uji - perbaiki, atau langsung bangun canggih?"},
{n:100,type:"open",micro:"Kapstone: proyek berpikir desain",q:"Rancang proyek berpikir desain lengkap untuk satu masalah nyata yang kamu pedulikan. Sertakan keenam bagian: (a) rencana empati (siapa, cara, pertanyaan), (b) pernyataan masalah + 1 wawasan, (c) pertanyaan 'bagaimana caranya kita' + minimal 4 ide + kriteria pemilihan, (d) ide terpilih + rencana prototipe + apa yang diuji, (e) rencana uji + rencana iterasi berdasar kemungkinan hasil, (f) pemeriksaan etika & aksesibilitas (siapa diuntungkan/dirugikan/tersisih & apa yang kamu lakukan). Buat tiap bagian cukup konkret untuk benar-benar dijalankan.",explain:"Jawaban baik: keenam bagian ada & konkret; empati melibatkan beberapa jenis pengguna; pernyataan masalah bebas solusi dengan wawasan yang menjelaskan 'kenapa'; minimal 4 ide berbeda + kriteria jelas; prototipe kasar & murah dengan hal spesifik yang diuji; rencana uji yang mengukur perilaku & rencana iterasi bercabang yang bisa kembali ke tahap sebelumnya; pemeriksaan etika yang menyebut pihak yang diuntungkan, yang menanggung beban, yang bisa tersisih (dengan perbaikan), & trade-off yang diakui jujur.",hint:"Bagian (e) & (f) yang paling membedakan proyek berpikir desain yang matang, iterasi harus bisa mengirimmu kembali ke empati/definisi, & pemeriksaan etika harus menyebut pihak yang menanggung beban, bukan hanya yang diuntungkan.",sample:"Masalah: siswa yang datang lebih awal (diantar orang tua sebelum kerja) menunggu di depan gerbang tanpa tempat berteduh atau kegiatan, kadang sampai 45 menit. (a) Empati: selama 3 hari aku datang pagi & mengamati; wawancara 6 siswa yang biasa datang awal + 2 satpam + 1 guru piket. Pertanyaan: 'Ceritakan pagimu dari turun dari kendaraan sampai gerbang dibuka, apa yang kamu lakukan & rasakan?', 'Kalau hujan atau panas, kamu berteduh di mana?', 'Apa yang membuat menunggu terasa lama atau tidak nyaman?' (b) Pernyataan masalah: 'Siswa yang datang lebih awal butuh tempat menunggu yang aman & nyaman serta cara mengisi waktu, karena mereka diantar mengikuti jadwal kerja orang tua & tiba jauh sebelum sekolah dibuka.' Wawasan: menunggu terasa buruk bukan hanya karena tidak ada kursi, tapi karena tidak ada yang bisa dilakukan & merasa 'terlantar' di luar pagar. (c) Bagaimana caranya kita: 'Bagaimana caranya kita membuat waktu tunggu pagi siswa yang datang awal jadi aman, nyaman, & berguna?' Ide: (1) buka satu ruang/selasar lebih awal dengan satu petugas; (2) 'sudut pagi' dengan bangku, buku, & permainan papan; (3) klub pagi opsional (olahraga ringan / membaca / membantu menyiapkan kelas) dengan guru sukarelawan bergilir; (4) jadwal antar-jemput bersama antar orang tua agar lebih sedikit yang datang terlalu awal; (5) kerja sama dengan perpyctakaan untuk buka 30 menit lebih pagi. Kriteria pemilihan: aman & terawasi, bisa dijalankan dengan tenaga yang benar-benar ada, tidak butuh dana besar, membantu dalam 2 minggu. (d) Ide terpilih: buka selasar dekat perpustakaan lebih awal dengan 'sudut pagi' sederhana (gabungan ide 1 & 2). Prototipe: pindahkan 2 bangku & 1 rak buku bekas ke selasar, minta satu petugas/guru piket hadir 30 menit lebih awal selama seminggu. Yang diuji: apakah siswa mau masuk & memakainya, apakah terasa aman & tertib, berapa yang datang. (e) Uji: seminggu; hitung jumlah siswa tiap pagi, amati apakah tertib, tanya 5 siswa & petugas bagaimana rasanya. Iterasi: jika ramai & tertib, LANJUT, tambah kegiatan ringan (ide 3) & usulkan jadi resmi. Jika sepi, cari tahu, mungkin lokasi kurang terlihat atau siswa tidak tahu, coba tanda & pengumuman, uji lagi. Jika ramai tapi kacau, tambah aturan sederhana & petugas, atau kembali ke DEFINISI kalau ternyata yang dibutuhkan berbeda. (f) Etika & aksesibilitas: Diuntungkan, siswa yang datang awal & orang tua mereka. Beban tambahan, petugas/guru yang harus datang lebih pagi, perlu sistem giliran yang adil & mungkin kompensasi waktu. Bisa tersisih, siswa dengan keterbatasan gerak jika selasarnya tidak mudah diakses kursi roda, & siswa yang datang awal di lokasi gerbang lain, perlu memastikan lokasi terjangkau & mempertimbangkan titik kedua. Trade-off yang tetap ada, membuka lebih pagi menambah beban staf; aku akan menjelaskannya terbuka & mengusulkan giliran + meminta dukungan sekolah, bukan mengandalkan kebaikan hati satu-dua orang terus-menerus."},
];
